package org.dextur.reputation.application;

import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import org.dextur.reputation.api.*;
import org.dextur.reputation.domain.policy.*;

/** Public read/evaluation service; administrative mutation remains an internal capability. */
public final class PolicyApplication implements ReputationPolicyService,AutoCloseable {
    private final ReputationApplication app;private final PolicyRepository repository;private final Settings settings;private final Clock clock;private final Consumer<Throwable> errors;
    private final BoundedCache<UUID,PolicyEngine.Input> cache;private final ConcurrentHashMap<String,String> connections=new ConcurrentHashMap<>();private final ConcurrentHashMap<String,Metadata> registrations=new ConcurrentHashMap<>();private final CopyOnWriteArrayList<Consumer<Changed>> listeners=new CopyOnWriteArrayList<>();private final Object activation=new Object();private final AutoCloseable observation;private volatile PolicyRules rules;private volatile boolean closed;
    public PolicyApplication(ReputationApplication app,PolicyRepository repository,Settings settings,PolicyRules rules,Clock clock,Consumer<Throwable> errors){this.app=app;this.repository=repository;this.settings=settings;this.rules=rules;this.clock=clock;this.errors=errors;cache=new BoundedCache<>(settings.cacheSize(),Duration.ofSeconds(settings.cacheSeconds()));observation=app.addProfileObserver(this::observe);}
    private void observe(ReputationSnapshot profile,boolean committed){cache.remove(profile.playerId());if(committed&&!closed){UUID operation=UUID.nameUUIDFromBytes((profile.scopeId()+"/"+profile.playerId()+"/"+profile.revision()+"/policy").getBytes(java.nio.charset.StandardCharsets.UTF_8));emit(new Changed(operation,profile.playerId(),"REPUTATION_POLICY_CHANGED",new ReputationPolicyResult.Revision(profile.revision(),-1,-1,rules.fingerprint())));}}
    public PolicyRules configuration(){return rules;}
    private boolean active(String id){var metadata=registrations.get(id);return id.equals("reputation.vote")||id.equals("health.maximum")&&rules.healthEnabled()||metadata!=null&&metadata.integrationActive()||connections.containsKey(id);}
    @Override public CompletionStage<ReputationPolicyResult> evaluate(UUID player,String id,Map<String,String> context){Objects.requireNonNull(player);PolicyRules.identifier(id);var copy=Map.copyOf(context);if(closed)return CompletableFuture.failedFuture(new IllegalStateException("Policy service closed"));return app.submit(()->app.withProfiles(player,player,()->{synchronized(activation){var input=repository.policyInput(player,settings.scope());app.updateProfile(input.profile(),false);cache.put(player,input);return PolicyEngine.evaluate(input,rules,id,copy,clock.instant(),active(id));}}));}
    @Override public Optional<ReputationPolicyResult> cached(UUID player,String id){if(closed)return Optional.empty();synchronized(activation){return cache.get(player).filter(input->app.cachedProfile(player).map(p->p.revision()==input.profile().revision()).orElse(false)).map(input->PolicyEngine.evaluate(input,rules,id,Map.of(),clock.instant(),active(id)));}}
    @Override public Map<String,Metadata> policies(){var result=new TreeMap<String,Metadata>();for(var d:rules.policies().values())result.put(d.id(),new Metadata(d.id(),d.names(),connections.getOrDefault(d.id(),"dexturreputation"),active(d.id())));for(var metadata:registrations.values())result.put(metadata.id(),new Metadata(metadata.id(),metadata.names(),connections.getOrDefault(metadata.id(),metadata.provider()),active(metadata.id())));return Collections.unmodifiableMap(result);}
    @Override public synchronized AutoCloseable register(Metadata metadata){Objects.requireNonNull(metadata);PolicyRules.identifier(metadata.id());PolicyRules.identifier(metadata.provider()+".integration");if(closed||PolicyRules.BUILT_INS.contains(metadata.id())||registrations.size()>=64||!metadata.names().keySet().containsAll(Set.of("ru_RU","en_US")))throw new IllegalArgumentException("Policy registration denied");var accepted=new Metadata(metadata.id(),metadata.names(),metadata.provider(),metadata.integrationActive());if(registrations.putIfAbsent(metadata.id(),accepted)!=null)throw new IllegalArgumentException("Policy collision");var open=new java.util.concurrent.atomic.AtomicBoolean(true);return ()->{if(open.compareAndSet(true,false))registrations.remove(metadata.id(),accepted);};}
    @Override public synchronized AutoCloseable connect(String policy,String provider){PolicyRules.identifier(policy);PolicyRules.identifier(provider+".integration");if(closed||connections.size()>=64||!rules.policies().containsKey(policy)||Set.of("reputation.vote","health.maximum","support.emergency-contact").contains(policy)||connections.putIfAbsent(policy,provider)!=null)throw new IllegalArgumentException("Policy connection denied");var open=new java.util.concurrent.atomic.AtomicBoolean(true);return ()->{if(open.compareAndSet(true,false))connections.remove(policy,provider);};}
    @Override public synchronized AutoCloseable onChanged(Consumer<Changed> listener){if(closed||listeners.size()>=128)throw new IllegalStateException("Policy listeners unavailable");listeners.add(Objects.requireNonNull(listener));var open=new java.util.concurrent.atomic.AtomicBoolean(true);return ()->{if(open.compareAndSet(true,false))listeners.remove(listener);};}
    private void emit(Changed event){for(var listener:listeners)try{listener.accept(event);}catch(Throwable error){try{errors.accept(error);}catch(Throwable ignored){/* Diagnostics must not change an already committed outcome. */}}}
    public CompletionStage<AdministrationData.Change> administer(AdministrationData.Request request){if(closed||!request.scope().equals(settings.scope()))return CompletableFuture.failedFuture(new IllegalStateException("Administration unavailable"));return app.submit(()->app.withProfiles(request.player(),request.player(),()->{synchronized(activation){if(request.type()==AdministrationData.Type.OVERRIDE&&!rules.policies().containsKey(request.policy()))throw new IllegalArgumentException("ADMIN_POLICY");var result=repository.administer(request);boolean effect=result.audit().previousAdmin()!=result.audit().resultingAdmin()||result.audit().previousLock()!=result.audit().resultingLock()||!result.audit().previousOverrides().equals(result.audit().resultingOverrides());app.updateProfile(result.profile(),!result.duplicate()&&effect);cache.remove(request.player());if(!result.duplicate()&&(effect||Set.of(AdministrationData.Type.SET,AdministrationData.Type.ADD,AdministrationData.Type.REMOVE).contains(request.type())))emit(new Changed(request.operation(),request.player(),switch(request.type()){case SET,ADD,REMOVE->"ADMINISTRATIVE_ADJUSTMENT_APPLIED";case LOCK,UNLOCK->"VOTING_LOCK_CHANGED";case OVERRIDE->"POLICY_OVERRIDE_CHANGED";},new ReputationPolicyResult.Revision(result.profile().revision(),result.state().revision(),-1,rules.fingerprint())));return result;}}));}
    public CompletionStage<AdministrationData.State> administration(UUID id){return app.submit(()->app.withProfiles(id,id,()->repository.policyInput(id,settings.scope()).administration()));}
    public CompletionStage<Void> reload(java.nio.file.Path directory){if(closed)return CompletableFuture.failedFuture(new IllegalStateException("Policy service closed"));return app.submit(()->{var candidate=PolicyConfiguration.load(directory);synchronized(activation){repository.features(candidate);rules=candidate;cache.clear();emit(new Changed(UUID.randomUUID(),new UUID(0,0),"POLICIES_RELOADED",new ReputationPolicyResult.Revision(-1,-1,-1,rules.fingerprint())));}return null;});}
    @Override public void close(){closed=true;cache.clear();listeners.clear();registrations.clear();connections.clear();try{observation.close();}catch(Exception e){errors.accept(e);}}
}
